# Tool Capability Registry demo: register, semantic search, honest limits.
REG={}
def register(name,verbs,inputs,outputs,limits):
    REG[name]={"verbs":verbs,"inputs":inputs,"outputs":outputs,"limits":limits}
def find(goal_words):
    out=[]
    for name,r in REG.items():
        score=sum(1 for w in goal_words if w in (" ".join(r["verbs"])+" "+r["outputs"]).lower())
        if score: out.append((score,name,r["limits"]))
    return sorted(out,reverse=True)
register("translator",["translate"],"text","text",{"max_chars":5000})
register("summarizer",["summarize"],"text","summary",{"max_chars":20000})
print(find(["translate","text"]))

